/**
 * Service worker registration wrapper — the ONLY place the app SW registers.
 *
 * Registers /sw.js (generated by vite-plugin-pwa) only in production builds
 * outside Lovable preview/iframe contexts. In any refused context it
 * unregisters stale app SWs instead, so previews never serve stale caches.
 */

const APP_SW_URL = "/sw.js";

function isRefusedContext(): boolean {
  if (!import.meta.env.PROD) return true;
  if (typeof window === "undefined") return true;
  if (window.self !== window.top) return true; // inside an iframe

  const host = window.location.hostname;
  if (host.startsWith("id-preview--") || host.startsWith("preview--"))
    return true;
  if (host === "lovableproject.com" || host.endsWith(".lovableproject.com"))
    return true;
  if (
    host === "lovableproject-dev.com" ||
    host.endsWith(".lovableproject-dev.com")
  )
    return true;
  if (host === "beta.lovable.dev" || host.endsWith(".beta.lovable.dev"))
    return true;

  if (new URLSearchParams(window.location.search).get("sw") === "off")
    return true;

  return false;
}

async function unregisterAppServiceWorkers(): Promise<void> {
  if (!("serviceWorker" in navigator)) return;
  const registrations = await navigator.serviceWorker.getRegistrations();
  await Promise.all(
    registrations
      .filter((reg) => {
        const scriptUrl =
          reg.active?.scriptURL ??
          reg.waiting?.scriptURL ??
          reg.installing?.scriptURL ??
          "";
        return scriptUrl.endsWith(APP_SW_URL);
      })
      .map((reg) => reg.unregister()),
  );
}

export async function registerServiceWorker(): Promise<void> {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;

  if (isRefusedContext()) {
    await unregisterAppServiceWorkers();
    return;
  }

  await navigator.serviceWorker.register(APP_SW_URL, { scope: "/" });
}
